import { useAuth } from "@/_core/hooks/useAuth";

/*
 * NCRRA Trusted Member Utility design system.
 * Calm ivory surfaces, deep navy hierarchy and quiet teal actions guide member services, registration and billing.
 */
import { useMemo, useState, type ReactNode } from "react";
import {
  ArrowDownUp,
  ArrowLeft,
  Bell,
  CalendarDays,
  Check,
  ChevronRight,
  CircleAlert,
  CircleCheck,
  CircleHelp,
  Clock3,
  CreditCard,
  Droplets,
  FileText,
  HeartHandshake,
  Home as HomeIcon,
  House,
  ListFilter,
  LockKeyhole,
  MapPin,
  Menu,
  Paperclip,
  PlugZap,
  ReceiptText,
  Search,
  ShieldCheck,
  Smartphone,
  Tag,
  Ticket,
  UserRound,
  UsersRound,
  WalletCards,
  X,
  Zap,
} from "lucide-react";
import { toast } from "sonner";

type Screen =
  | "home"
  | "services"
  | "serviceRequest"
  | "issueDetails"
  | "reviewRequest"
  | "tickets"
  | "ticket"
  | "membership"
  | "payment"
  | "receipt"
  | "community"
  | "benefits"
  | "notifications"
  | "account"
  | "welcome"
  | "profileSetup"
  | "membershipConsent"
  | "registrationComplete";

type NavKey = "home" | "services" | "community" | "benefits" | "account";
type TicketStatus = "All" | "Awaiting provider" | "In progress" | "Resolved" | "Closed";
type TicketService = "All" | "Electricity" | "Water" | "Property";
type TicketSort = "newest" | "oldest" | "status";

type TicketRecord = {
  id: string;
  title: string;
  service: Exclude<TicketService, "All">;
  status: Exclude<TicketStatus, "All">;
  updated: string;
  order: number;
  detail: string;
};

const screenLabels: Record<Screen, string> = {
  home: "Home", services: "Services", serviceRequest: "Choose service", issueDetails: "Describe issue", reviewRequest: "Review request",
  tickets: "My tickets", ticket: "Ticket details", membership: "My membership", payment: "Pay contribution", receipt: "Contribution received",
  community: "Community", benefits: "Member benefits", notifications: "Notifications", account: "Account", welcome: "Welcome to NCRRA",
  profileSetup: "Set up profile", membershipConsent: "Review consent", registrationComplete: "Registration complete",
};

const navTarget: Record<NavKey, Screen> = { home: "home", services: "services", community: "community", benefits: "benefits", account: "account" };
const serviceFlow: Screen[] = ["serviceRequest", "issueDetails", "reviewRequest", "ticket"];
const registrationFlow: Screen[] = ["welcome", "profileSetup", "membershipConsent", "registrationComplete"];

const visualReferences = [
  { label: "Issue routing", src: "/manus-storage/ncrra-service-request_22e2ddb5.png" },
  { label: "Issue detail", src: "/manus-storage/ncrra-issue-details_e5ec3837.png" },
  { label: "Contribution", src: "/manus-storage/ncrra-payment-contribution_91cc764f.png" },
  { label: "Receipt", src: "/manus-storage/ncrra-payment-receipt_ce181408.png" },
];

const ticketRecords: TicketRecord[] = [
  { id: "NCRRA-2481", title: "Power interruption follow-up", service: "Electricity", status: "Awaiting provider", updated: "Updated today · 11:20 AM", order: 4, detail: "Power supply has not been restored since morning at the linked meter." },
  { id: "NCRRA-2458", title: "Intermittent water supply", service: "Water", status: "In progress", updated: "Updated yesterday · 04:15 PM", order: 3, detail: "Member reported low pressure at the saved water connection." },
  { id: "NCRRA-2419", title: "Estate streetlight repair", service: "Property", status: "Resolved", updated: "Resolved 06 May 2025", order: 2, detail: "The maintenance team confirmed that the streetlight was repaired." },
  { id: "NCRRA-2397", title: "Meter account detail correction", service: "Electricity", status: "Closed", updated: "Closed 28 Apr 2025", order: 1, detail: "The account correction request was completed and closed." },
];

function Orb({ children, tone = "mint" }: { children: ReactNode; tone?: "mint" | "amber" | "coral" }) {
  const tones = { mint: "bg-[#edf7f5] text-[#007b78]", amber: "bg-[#fff4dd] text-[#a76b10]", coral: "bg-[#fff0ec] text-[#d65c45]" };
  return <span className={`flex size-11 shrink-0 items-center justify-center rounded-full ${tones[tone]}`}>{children}</span>;
}

function Badge({ children, tone = "teal" }: { children: ReactNode; tone?: "teal" | "amber" | "coral" | "slate" }) {
  const tones = { teal: "bg-[#e8f5f2] text-[#007b78]", amber: "bg-[#fff3da] text-[#9a650f]", coral: "bg-[#fff0ec] text-[#c9503c]", slate: "bg-[#eef0f3] text-[#475569]" };
  return <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-extrabold ${tones[tone]}`}>{children}</span>;
}

function PrimaryButton({ children, onClick, disabled = false }: { children: ReactNode; onClick: () => void; disabled?: boolean }) {
  return <button disabled={disabled} onClick={onClick} className={`app-press flex h-12 w-full items-center justify-center rounded-xl px-5 text-sm font-extrabold ${disabled ? "cursor-not-allowed bg-[#cbd5d3] text-white" : "bg-[#007b78] text-white shadow-[0_8px_20px_rgba(0,123,120,0.18)]"}`}>{children}</button>;
}

function Header({ title, onBack, action }: { title: string; onBack?: () => void; action?: ReactNode }) {
  return <header className="flex items-center justify-between px-5 pb-4 pt-6"><div className="flex items-center gap-3">{onBack && <button onClick={onBack} className="app-press -ml-1 flex size-9 items-center justify-center rounded-full text-[#0b1e3b] hover:bg-[#edf7f5]" aria-label="Back"><ArrowLeft className="size-6" /></button>}<h1 className="font-display text-[27px] font-extrabold tracking-[-0.055em] text-[#0b1e3b]">{title}</h1></div>{action}</header>;
}

function ListRow({ icon, title, subtitle, onClick, end }: { icon: ReactNode; title: string; subtitle?: string; onClick?: () => void; end?: ReactNode }) {
  const inner = <><Orb>{icon}</Orb><span className="min-w-0 flex-1 text-left"><span className="block text-[15px] font-extrabold tracking-[-0.02em] text-[#0b1e3b]">{title}</span>{subtitle && <span className="mt-0.5 block text-[12px] leading-5 text-[#5b6473]">{subtitle}</span>}</span>{end ?? <ChevronRight className="size-5 text-[#0b1e3b]" />}</>;
  return onClick ? <button onClick={onClick} className="app-press flex w-full items-center gap-3 py-3.5 text-left">{inner}</button> : <div className="flex items-center gap-3 py-3.5">{inner}</div>;
}

function BottomNav({ active, onNavigate }: { active: NavKey; onNavigate: (screen: Screen) => void }) {
  const items: { key: NavKey; label: string; icon: ReactNode }[] = [
    { key: "home", label: "Home", icon: <HomeIcon className="size-5" /> }, { key: "services", label: "Services", icon: <Menu className="size-5" /> },
    { key: "community", label: "Community", icon: <UsersRound className="size-5" /> }, { key: "benefits", label: "Benefits", icon: <Tag className="size-5" /> }, { key: "account", label: "Account", icon: <UserRound className="size-5" /> },
  ];
  return <nav className="sticky bottom-0 z-20 mt-auto border-t border-[#e4e7e6] bg-[#fffdfa]/95 px-2 pb-2 pt-2 backdrop-blur-lg"><div className="grid grid-cols-5">{items.map((item) => { const selected = active === item.key; return <button key={item.key} onClick={() => onNavigate(navTarget[item.key])} className={`app-press relative flex flex-col items-center gap-1 py-1 text-[10px] font-bold ${selected ? "text-[#007b78]" : "text-[#65707b]"}`}>{selected && <span className="absolute -top-2 h-1 w-10 rounded-full bg-[#007b78]" />}{item.icon}<span>{item.label}</span></button>; })}</div></nav>;
}

function Progress({ step, label = "Service request" }: { step: number; label?: string }) { return <div className="flex items-center gap-2"><Badge tone="slate">{step} of 3</Badge><span className="text-xs font-bold text-[#65707b]">{label}</span></div>; }

function RegistrationProgress({ step }: { step: number }) { return <div className="flex items-center gap-2"><Badge tone="slate">{step} of 3</Badge><span className="text-xs font-bold text-[#65707b]">Member registration</span></div>; }

function statusTone(status: TicketRecord["status"]): "teal" | "amber" | "slate" {
  if (status === "Awaiting provider") return "amber";
  if (status === "Resolved") return "teal";
  return "slate";
}

export default function Home() {
  // The useAuth hook provides authentication state.
  // To implement login/logout, call logout(), or start login from an event
  // handler: onClick={() => startLogin()} (imported from "@/const"). Never call
  // startLogin() during render (no href={startLogin()}) — it mints a one-time
  // nonce cookie and must run only at the moment of navigation.
  let { user, loading, error, isAuthenticated, logout } = useAuth();

  const [screen, setScreen] = useState<Screen>(() => {
    const requested = new URLSearchParams(window.location.search).get("screen") as Screen | null;
    return requested && requested in screenLabels ? requested : "home";
  });
  const [trail, setTrail] = useState<Screen[]>([]);
  const [issueText, setIssueText] = useState("No supply since this morning.");
  const [routingConsent, setRoutingConsent] = useState(true);
  const [method, setMethod] = useState<"mpesa" | "card">("mpesa");
  const [confirming, setConfirming] = useState(false);
  const [profile, setProfile] = useState({ fullName: "Amina Wanjiku", email: "amina@example.com", phone: "0712 345 678", area: "Nairobi" });
  const [registrationConsent, setRegistrationConsent] = useState({ membership: false, privacy: false, communications: true });
  const [ticketQuery, setTicketQuery] = useState("");
  const [ticketStatus, setTicketStatus] = useState<TicketStatus>("All");
  const [ticketService, setTicketService] = useState<TicketService>("All");
  const [ticketSort, setTicketSort] = useState<TicketSort>("newest");
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [selectedTicket, setSelectedTicket] = useState<TicketRecord>(ticketRecords[0]);

  const navigate = (next: Screen) => { setTrail((value) => [...value, screen]); setScreen(next); };
  const navigateRoot = (next: Screen) => { setTrail([]); setScreen(next); };
  const goBack = () => { const previous = trail.at(-1) ?? "home"; setTrail((value) => value.slice(0, -1)); setScreen(previous); };
  const activeNav = useMemo<NavKey>(() => {
    if (["services", "serviceRequest", "issueDetails", "reviewRequest", "tickets", "ticket"].includes(screen)) return "services";
    if (["membership", "payment", "receipt", "welcome", "profileSetup", "membershipConsent", "registrationComplete"].includes(screen)) return "account";
    return screen as NavKey;
  }, [screen]);
  const filteredTickets = useMemo(() => {
    const query = ticketQuery.trim().toLowerCase();
    const result = ticketRecords.filter((ticket) => (ticketStatus === "All" || ticket.status === ticketStatus) && (ticketService === "All" || ticket.service === ticketService) && (!query || `${ticket.id} ${ticket.title} ${ticket.service}`.toLowerCase().includes(query)));
    return [...result].sort((a, b) => ticketSort === "oldest" ? a.order - b.order : ticketSort === "status" ? a.status.localeCompare(b.status) : b.order - a.order);
  }, [ticketQuery, ticketService, ticketSort, ticketStatus]);
  const requiredConsentComplete = registrationConsent.membership && registrationConsent.privacy;
  const onboardingScreen = ["welcome", "profileSetup", "membershipConsent", "registrationComplete"].includes(screen);

  const screenView = () => {
    if (screen === "welcome") return <div className="flex min-h-[740px] flex-col px-5 pb-7 pt-7"><div className="flex items-center gap-2.5"><img src="/manus-storage/ncrra-mark_917a6721.png" alt="NCRRA mark" className="size-10 object-contain" /><span className="font-display text-[27px] font-extrabold tracking-[-0.07em]">NCRRA</span></div><div className="mt-14"><Badge>New member registration</Badge><h1 className="mt-5 font-display text-[34px] font-extrabold leading-[1.06] tracking-[-0.065em]">Your association services, in one place.</h1><p className="mt-4 text-[15px] leading-6 text-[#5b6473]">Set up your member account first. You can add service connections and manage your annual contribution afterwards.</p></div><div className="mt-10 space-y-4 border-y border-[#dce7e4] py-5"><div className="flex gap-3"><Orb><UserRound className="size-5" /></Orb><div><p className="text-sm font-extrabold">Set up your member profile</p><p className="mt-1 text-xs leading-5 text-[#5b6473]">Confirm how NCRRA can reach you.</p></div></div><div className="flex gap-3"><Orb><ShieldCheck className="size-5" /></Orb><div><p className="text-sm font-extrabold">Review data consent</p><p className="mt-1 text-xs leading-5 text-[#5b6473]">See what data is used and why before you continue.</p></div></div><div className="flex gap-3"><Orb><HeartHandshake className="size-5" /></Orb><div><p className="text-sm font-extrabold">Access member services</p><p className="mt-1 text-xs leading-5 text-[#5b6473]">Manage services, notices, benefits and annual contributions.</p></div></div></div><div className="mt-auto"><PrimaryButton onClick={() => navigate("profileSetup")}>Start registration</PrimaryButton><button onClick={() => navigateRoot("home")} className="app-press mt-3 w-full text-sm font-extrabold text-[#007b78]">I already have an account</button></div></div>;

    if (screen === "profileSetup") return <><Header title="Set up profile" onBack={goBack} /><div className="px-5"><RegistrationProgress step={1} /><h2 className="mt-4 font-display text-[21px] font-extrabold tracking-[-0.05em]">A few details to get started</h2><p className="mt-2 text-sm leading-6 text-[#5b6473]">These details identify your NCRRA membership and let support respond to you.</p><div className="mt-6 space-y-4"><label className="block text-sm font-extrabold">Full name<input value={profile.fullName} onChange={(event) => setProfile({ ...profile, fullName: event.target.value })} className="mt-2 h-12 w-full rounded-xl border border-[#dce1e0] bg-white px-3 text-sm font-medium outline-none focus:border-[#007b78]" /></label><label className="block text-sm font-extrabold">Email address<input value={profile.email} onChange={(event) => setProfile({ ...profile, email: event.target.value })} className="mt-2 h-12 w-full rounded-xl border border-[#dce1e0] bg-white px-3 text-sm font-medium outline-none focus:border-[#007b78]" /></label><label className="block text-sm font-extrabold">Mobile number<input value={profile.phone} onChange={(event) => setProfile({ ...profile, phone: event.target.value })} className="mt-2 h-12 w-full rounded-xl border border-[#dce1e0] bg-white px-3 text-sm font-medium outline-none focus:border-[#007b78]" /></label><label className="block text-sm font-extrabold">Town or area<input value={profile.area} onChange={(event) => setProfile({ ...profile, area: event.target.value })} className="mt-2 h-12 w-full rounded-xl border border-[#dce1e0] bg-white px-3 text-sm font-medium outline-none focus:border-[#007b78]" /></label></div><div className="mt-7"><PrimaryButton onClick={() => profile.fullName && profile.email && profile.phone ? navigate("membershipConsent") : toast("Complete your contact details to continue.")}>Continue</PrimaryButton></div></div></>;

    if (screen === "membershipConsent") return <><Header title="Review consent" onBack={goBack} /><div className="px-5"><RegistrationProgress step={2} /><h2 className="mt-4 font-display text-[21px] font-extrabold tracking-[-0.05em]">You decide how your data is used</h2><p className="mt-2 text-sm leading-6 text-[#5b6473]">NCRRA needs a limited set of details to manage membership. Provider references are not connected until you choose to add them.</p><div className="mt-6 divide-y divide-[#e5e9e7] rounded-2xl border border-[#e3e6e5] bg-white px-4"><button onClick={() => setRegistrationConsent({ ...registrationConsent, membership: !registrationConsent.membership })} className="app-press flex w-full gap-3 py-4 text-left"><span className={`mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-md border ${registrationConsent.membership ? "border-[#007b78] bg-[#007b78] text-white" : "border-[#b8c0c6] bg-white"}`}>{registrationConsent.membership && <Check className="size-3.5" />}</span><span><span className="block text-sm font-extrabold">Membership administration <span className="text-[#c9503c]">Required</span></span><span className="mt-1 block text-xs leading-5 text-[#5b6473]">Use my profile details to create and administer my NCRRA membership.</span></span></button><button onClick={() => setRegistrationConsent({ ...registrationConsent, privacy: !registrationConsent.privacy })} className="app-press flex w-full gap-3 py-4 text-left"><span className={`mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-md border ${registrationConsent.privacy ? "border-[#007b78] bg-[#007b78] text-white" : "border-[#b8c0c6] bg-white"}`}>{registrationConsent.privacy && <Check className="size-3.5" />}</span><span><span className="block text-sm font-extrabold">Privacy notice <span className="text-[#c9503c]">Required</span></span><span className="mt-1 block text-xs leading-5 text-[#5b6473]">I have reviewed how NCRRA safeguards membership data and handles support access.</span></span></button><button onClick={() => setRegistrationConsent({ ...registrationConsent, communications: !registrationConsent.communications })} className="app-press flex w-full gap-3 py-4 text-left"><span className={`mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-md border ${registrationConsent.communications ? "border-[#007b78] bg-[#007b78] text-white" : "border-[#b8c0c6] bg-white"}`}>{registrationConsent.communications && <Check className="size-3.5" />}</span><span><span className="block text-sm font-extrabold">Association updates <span className="font-medium text-[#65707b]">Optional</span></span><span className="mt-1 block text-xs leading-5 text-[#5b6473]">Send association announcements, activities and relevant member notices.</span></span></button></div><div className="mt-5 rounded-xl bg-[#f1f8f6] px-3 py-3 text-xs leading-5 text-[#3c5558]"><ShieldCheck className="mr-1 inline size-4 text-[#007b78]" /> You can review or change optional communication choices later in Account. Service-provider data remains separate and is only shared for a requested service action.</div><div className="mt-6"><PrimaryButton disabled={!requiredConsentComplete} onClick={() => navigate("registrationComplete")}>Complete registration</PrimaryButton></div></div></>;

    if (screen === "registrationComplete") return <div className="flex min-h-[740px] flex-col px-5 pb-7 pt-7"><div className="flex items-center gap-2.5"><img src="/manus-storage/ncrra-mark_917a6721.png" alt="NCRRA mark" className="size-10 object-contain" /><span className="font-display text-[27px] font-extrabold tracking-[-0.07em]">NCRRA</span></div><div className="my-auto text-center"><span className="mx-auto flex size-20 items-center justify-center rounded-full bg-[#e8f5f2] text-[#007b78]"><CircleCheck className="size-11" /></span><Badge tone="teal">Registration complete</Badge><h1 className="mt-5 font-display text-[30px] font-extrabold leading-tight tracking-[-0.06em]">Welcome, {profile.fullName.split(" ")[0] || "member"}.</h1><p className="mt-3 text-sm leading-6 text-[#5b6473]">Your member account is ready. You can now save a service connection, review notices and manage your association contribution.</p><div className="mt-7 rounded-2xl border border-[#dce9e5] bg-[#f1f8f6] p-4 text-left"><p className="text-xs font-extrabold uppercase tracking-[0.12em] text-[#007b78]">Next recommended step</p><p className="mt-2 text-sm font-extrabold">Add your first service connection</p><p className="mt-1 text-xs leading-5 text-[#5b6473]">This is optional. A connection is saved only after you choose to add it.</p></div></div><PrimaryButton onClick={() => { navigateRoot("home"); toast("Your NCRRA registration is complete."); }}>Enter member app</PrimaryButton></div>;

    if (screen === "home") return <><div className="px-5 pb-3 pt-7"><div className="flex items-center justify-between"><div className="flex items-center gap-2.5"><img src="/manus-storage/ncrra-mark_917a6721.png" alt="NCRRA mark" className="size-10 object-contain" /><span className="font-display text-[27px] font-extrabold tracking-[-0.07em]">NCRRA</span></div><button onClick={() => navigate("notifications")} className="app-press relative flex size-10 items-center justify-center rounded-full hover:bg-[#edf7f5]"><Bell className="size-6" /><span className="absolute right-1 top-1 flex size-4 items-center justify-center rounded-full bg-[#fa6b60] text-[9px] font-extrabold text-white">2</span></button></div><h1 className="mt-6 font-display text-[25px] font-extrabold tracking-[-0.055em]">Good morning, Amina</h1><p className="mt-1 text-sm text-[#5b6473]">Your member services, in one place.</p></div><div className="mx-5 rounded-2xl border border-[#dce9e5] bg-[#f1f8f6] p-4"><div className="flex gap-3"><Orb><HeartHandshake className="size-6" /></Orb><div className="min-w-0 flex-1"><p className="text-[15px] font-extrabold">NCRRA member <span className="text-[#007b78]">· Active</span></p><p className="mt-1 text-xs text-[#5b6473]">Member since 12 Jan 2023</p><p className="mt-1 text-xs text-[#5b6473]">Membership ID: NCRRA-000784</p></div></div><button onClick={() => navigate("membership")} className="app-press mt-3 flex h-10 w-full items-center justify-center gap-2 rounded-xl border border-[#007b78] bg-white text-sm font-extrabold text-[#007b78]"><CreditCard className="size-4" /> View membership</button></div><section className="px-5 pt-6"><h2 className="font-display text-[17px] font-extrabold tracking-[-0.04em]">Quick actions</h2><div className="mt-3 grid grid-cols-2 gap-3"><button onClick={() => navigate("serviceRequest")} className="app-press rounded-2xl border border-[#e3e6e5] bg-white p-3.5 text-left"><Orb><CircleAlert className="size-5" /></Orb><p className="mt-3 text-sm font-extrabold">Report an issue</p><p className="mt-1 text-xs leading-4 text-[#5b6473]">Get help with a local service</p></button><button onClick={() => navigate("tickets")} className="app-press rounded-2xl border border-[#e3e6e5] bg-white p-3.5 text-left"><Orb><Ticket className="size-5" /></Orb><p className="mt-3 text-sm font-extrabold">My tickets</p><p className="mt-1 text-xs leading-4 text-[#5b6473]">Search and track requests</p></button><button onClick={() => navigate("payment")} className="app-press rounded-2xl border border-[#e3e6e5] bg-white p-3.5 text-left"><Orb><WalletCards className="size-5" /></Orb><p className="mt-3 text-sm font-extrabold">Pay contribution</p><p className="mt-1 text-xs leading-4 text-[#5b6473]">Manage your annual contribution</p></button><button onClick={() => navigate("services")} className="app-press rounded-2xl border border-[#e3e5e4] bg-white p-3.5 text-left"><Orb><PlugZap className="size-5" /></Orb><p className="mt-3 text-sm font-extrabold">My connections</p><p className="mt-1 text-xs leading-4 text-[#5b6473]">Reuse verified service details</p></button></div><button onClick={() => navigateRoot("welcome")} className="app-press mt-5 w-full text-center text-xs font-extrabold text-[#007b78]">New to NCRRA? Start member registration</button></section><section className="px-5 pb-5 pt-6"><div className="flex items-center justify-between"><h2 className="font-display text-[17px] font-extrabold tracking-[-0.04em]">My open ticket</h2><button onClick={() => navigate("tickets")} className="text-xs font-extrabold text-[#007b78]">View all</button></div><button onClick={() => { setSelectedTicket(ticketRecords[0]); navigate("ticket"); }} className="app-press mt-3 w-full rounded-2xl border border-[#e3e6e5] bg-white p-4 text-left"><div className="flex items-start gap-3"><Orb tone="amber"><Zap className="size-5" /></Orb><div className="flex-1"><Badge tone="amber">Awaiting provider</Badge><p className="mt-2 text-sm font-extrabold">NCRRA-2481</p><p className="mt-1 text-[13px] text-[#253752]">Power interruption follow-up</p><p className="mt-1.5 text-xs text-[#65707b]">Reported 10 May 2025 · 09:15 AM</p></div><ChevronRight className="mt-8 size-5" /></div></button></section></>;

    if (screen === "services") return <><Header title="Services" action={<Search className="size-6 text-[#007b78]" />} /><div className="px-5"><p className="text-[17px] font-extrabold">What do you need help with?</p><div className="mt-5 flex h-12 items-center gap-3 rounded-xl border border-[#dce1e0] bg-white px-4 text-sm text-[#7a8390]"><Search className="size-5" /> Search services</div><h2 className="mt-8 font-display text-[17px] font-extrabold">Your saved connections</h2><div className="mt-3 divide-y divide-[#e9eceb] rounded-2xl border border-[#e3e6e5] bg-white px-4"><ListRow icon={<PlugZap className="size-5" />} title="KPLC · Meter ending 7842" end={<Badge>Verified</Badge>} /><ListRow icon={<Droplets className="size-5" />} title="Mowasco · Account ending 2910" end={<Badge>Verified</Badge>} /></div><button onClick={() => navigate("serviceRequest")} className="app-press mt-3 flex w-full items-center justify-center gap-2 rounded-xl border border-dashed border-[#8abebb] py-3 text-sm font-extrabold text-[#007b78]"><PlugZap className="size-4" /> Add another connection</button><h2 className="mt-8 font-display text-[17px] font-extrabold">Browse services</h2><div className="mt-3 divide-y divide-[#e9eceb] rounded-2xl border border-[#e3e6e5] bg-white px-4"><ListRow onClick={() => navigate("serviceRequest")} icon={<Zap className="size-5" />} title="Electricity" /><ListRow onClick={() => navigate("serviceRequest")} icon={<Droplets className="size-5" />} title="Water" /><ListRow onClick={() => navigate("serviceRequest")} icon={<House className="size-5" />} title="Property maintenance" /><ListRow onClick={() => navigate("serviceRequest")} icon={<CircleHelp className="size-5" />} title="Other help" /></div></div></>;

    if (screen === "serviceRequest") return <><Header title="Report a service issue" onBack={goBack} /><div className="px-5"><Progress step={1} /><h2 className="mt-4 font-display text-[21px] font-extrabold tracking-[-0.05em]">Which service needs attention?</h2><div className="mt-5 rounded-2xl border border-[#dce9e5] bg-[#f1f8f6] p-4"><div className="flex gap-3"><Orb><PlugZap className="size-5" /></Orb><div className="flex-1"><p className="text-sm font-extrabold">KPLC · Meter ending 7842</p><p className="mt-1 text-xs text-[#5b6473]">Verified connection</p></div><button onClick={() => toast("Connection selection is part of the production flow.")} className="text-xs font-extrabold text-[#007b78]">Change</button></div></div><div className="mt-6 space-y-3"><button onClick={() => navigate("issueDetails")} className="app-press flex w-full items-center gap-3 rounded-2xl border-2 border-[#007b78] bg-[#f3fbfa] p-4 text-left"><Orb><Zap className="size-5" /></Orb><span className="flex-1 text-sm font-extrabold">Electricity</span><CircleCheck className="size-5 text-[#007b78]" /></button>{[[<Droplets className="size-5" />, "Water"], [<House className="size-5" />, "Property maintenance"], [<CircleHelp className="size-5" />, "Other help"]].map(([icon, label]) => <button key={String(label)} onClick={() => toast("Select Electricity to continue in this prototype.")} className="app-press flex w-full items-center gap-3 rounded-2xl border border-[#e3e6e5] bg-white p-4 text-left"><Orb>{icon as ReactNode}</Orb><span className="text-sm font-extrabold">{label as ReactNode}</span></button>)}</div><p className="mt-5 text-xs leading-5 text-[#65707b]">We use this connection only to route your request.</p></div></>;

    if (screen === "issueDetails") return <><Header title="Describe the issue" onBack={goBack} /><div className="px-5"><Progress step={2} /><div className="mt-4 rounded-xl border border-[#dce9e5] bg-[#f1f8f6] px-3 py-2.5"><p className="text-xs font-extrabold uppercase tracking-[0.12em] text-[#007b78]">Electricity</p><p className="mt-0.5 text-sm font-extrabold">Meter ending 7842</p></div><label className="mt-6 block text-sm font-extrabold">What happened?</label><div className="mt-2"><Badge>Power interruption</Badge></div><label className="mt-6 block text-sm font-extrabold">Tell us more</label><textarea value={issueText} onChange={(event) => setIssueText(event.target.value)} className="mt-2 h-28 w-full resize-none rounded-xl border border-[#dce1e0] bg-white p-3 text-sm leading-6 outline-none focus:border-[#007b78]" /><button onClick={() => toast("Attachment picker is included in the Flutter implementation handoff.")} className="app-press mt-3 flex w-full items-center gap-3 rounded-xl border border-dashed border-[#9cbfbc] bg-white px-3 py-3 text-left"><Paperclip className="size-5 text-[#007b78]" /><span><span className="block text-sm font-extrabold">Add a photo or document</span><span className="block text-xs text-[#65707b]">Optional evidence for NCRRA support</span></span></button><button onClick={() => setRoutingConsent((value) => !value)} className="app-press mt-4 flex items-start gap-3 text-left"><span className={`mt-0.5 flex size-5 items-center justify-center rounded-md border ${routingConsent ? "border-[#007b78] bg-[#007b78] text-white" : "border-[#b8c0c6] bg-white"}`}>{routingConsent && <Check className="size-3.5" />}</span><span className="text-xs leading-5 text-[#435166]">Share this meter reference with NCRRA support so the request can be routed correctly.</span></button><div className="mt-6"><PrimaryButton onClick={() => navigate("reviewRequest")}>Review request</PrimaryButton></div></div></>;

    if (screen === "reviewRequest") return <><Header title="Review request" onBack={goBack} /><div className="px-5"><Progress step={3} /><h2 className="mt-4 font-display text-[21px] font-extrabold tracking-[-0.05em]">Check before sending</h2><div className="mt-5 rounded-2xl border border-[#e3e6e5] bg-white p-4"><div className="flex gap-3"><Orb><Zap className="size-5" /></Orb><div><p className="text-sm font-extrabold">Power interruption</p><p className="mt-1 text-xs text-[#5b6473]">KPLC · Meter ending 7842</p></div></div><div className="mt-5 border-t border-[#edf0ef] pt-4"><p className="text-xs font-extrabold uppercase tracking-[0.12em] text-[#65707b]">Description</p><p className="mt-2 text-sm leading-6 text-[#253752]">{issueText}</p></div><div className="mt-5 border-t border-[#edf0ef] pt-4 text-sm"><div className="flex justify-between"><span className="text-[#65707b]">Routing</span><b>NCRRA Support</b></div><div className="mt-3 flex justify-between"><span className="text-[#65707b]">Response target</span><b>1 business day</b></div></div></div><p className="mt-4 text-xs leading-5 text-[#65707b]">Submitting creates a service ticket and permits NCRRA to route the saved service reference only to the responsible support party.</p><div className="mt-6"><PrimaryButton onClick={() => { setSelectedTicket(ticketRecords[0]); navigate("ticket"); }}>Submit request</PrimaryButton></div></div></>;

    if (screen === "tickets") return <><Header title="My tickets" onBack={goBack} action={<button onClick={() => setFiltersOpen((value) => !value)} className={`app-press flex size-10 items-center justify-center rounded-full ${filtersOpen ? "bg-[#e8f5f2] text-[#007b78]" : "text-[#0b1e3b]"}`} aria-label="Toggle filters">{filtersOpen ? <X className="size-5" /> : <ListFilter className="size-5" />}</button>} /><div className="px-5"><div className="flex h-12 items-center gap-3 rounded-xl border border-[#dce1e0] bg-white px-3"><Search className="size-5 shrink-0 text-[#65707b]" /><input value={ticketQuery} onChange={(event) => setTicketQuery(event.target.value)} placeholder="Search ticket or service" className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-[#83909e]" />{ticketQuery && <button onClick={() => setTicketQuery("")} className="app-press text-[#65707b]" aria-label="Clear ticket search"><X className="size-4" /></button>}</div><div className="mt-3 flex gap-2 overflow-x-auto pb-1">{(["All", "Awaiting provider", "In progress", "Resolved"] as TicketStatus[]).map((item) => <button key={item} onClick={() => setTicketStatus(item)} className={`app-press whitespace-nowrap rounded-full px-3 py-2 text-xs font-extrabold ${ticketStatus === item ? "bg-[#007b78] text-white" : "bg-white text-[#5b6473] ring-1 ring-[#dce3e1]"}`}>{item}</button>)}</div>{filtersOpen && <div className="mt-4 rounded-2xl border border-[#dce9e5] bg-[#f1f8f6] p-4"><div className="flex items-center justify-between"><p className="text-sm font-extrabold">Filter and sort</p><button onClick={() => { setTicketStatus("All"); setTicketService("All"); setTicketSort("newest"); }} className="text-xs font-extrabold text-[#007b78]">Reset</button></div><div className="mt-4 grid grid-cols-2 gap-3"><label className="text-xs font-extrabold text-[#435166]">Service<select value={ticketService} onChange={(event) => setTicketService(event.target.value as TicketService)} className="mt-1.5 h-10 w-full rounded-lg border border-[#cddfdb] bg-white px-2 text-sm font-bold text-[#0b1e3b] outline-none"><option>All</option><option>Electricity</option><option>Water</option><option>Property</option></select></label><label className="text-xs font-extrabold text-[#435166]">Sort<select value={ticketSort} onChange={(event) => setTicketSort(event.target.value as TicketSort)} className="mt-1.5 h-10 w-full rounded-lg border border-[#cddfdb] bg-white px-2 text-sm font-bold text-[#0b1e3b] outline-none"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="status">Status</option></select></label></div></div>}<div className="mt-6 flex items-center justify-between"><p className="text-sm font-extrabold">{filteredTickets.length} ticket{filteredTickets.length === 1 ? "" : "s"} found</p><span className="flex items-center gap-1 text-xs font-bold text-[#65707b]"><ArrowDownUp className="size-3.5" /> {ticketSort === "newest" ? "Newest" : ticketSort === "oldest" ? "Oldest" : "Status"}</span></div><div className="mt-3 space-y-3">{filteredTickets.map((ticket) => <button key={ticket.id} onClick={() => { setSelectedTicket(ticket); navigate("ticket"); }} className="app-press w-full rounded-2xl border border-[#e3e6e5] bg-white p-4 text-left"><div className="flex gap-3"><Orb tone={ticket.status === "Awaiting provider" ? "amber" : "mint"}>{ticket.service === "Electricity" ? <Zap className="size-5" /> : ticket.service === "Water" ? <Droplets className="size-5" /> : <House className="size-5" />}</Orb><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><p className="text-sm font-extrabold">{ticket.id}</p><Badge tone={statusTone(ticket.status)}>{ticket.status}</Badge></div><p className="mt-1 text-[13px] font-bold text-[#253752]">{ticket.title}</p><p className="mt-1.5 text-xs text-[#65707b]">{ticket.service} · {ticket.updated}</p></div><ChevronRight className="mt-7 size-5 shrink-0 text-[#65707b]" /></div></button>)}</div>{filteredTickets.length === 0 && <div className="mt-8 text-center"><span className="mx-auto flex size-12 items-center justify-center rounded-full bg-[#eef5f3] text-[#007b78]"><Search className="size-5" /></span><p className="mt-3 text-sm font-extrabold">No matching tickets</p><p className="mt-1 text-xs leading-5 text-[#65707b]">Try a different service, status or search term.</p><button onClick={() => { setTicketQuery(""); setTicketStatus("All"); setTicketService("All"); }} className="app-press mt-3 text-xs font-extrabold text-[#007b78]">Clear filters</button></div>}</div></>;

    if (screen === "ticket") return <><Header title="Ticket details" onBack={goBack} /><div className="px-5"><div className="rounded-2xl border border-[#e3e6e5] bg-white p-4"><div className="flex gap-3"><Orb tone={selectedTicket.status === "Awaiting provider" ? "amber" : "mint"}>{selectedTicket.service === "Electricity" ? <Zap className="size-5" /> : selectedTicket.service === "Water" ? <Droplets className="size-5" /> : <House className="size-5" />}</Orb><div className="flex-1"><Badge tone={statusTone(selectedTicket.status)}>{selectedTicket.status}</Badge><h2 className="mt-3 font-display text-xl font-extrabold tracking-[-0.05em]">{selectedTicket.id}</h2><p className="mt-1 text-sm">{selectedTicket.title}</p><p className="mt-2 text-xs text-[#65707b]">{selectedTicket.service} · {selectedTicket.updated}</p></div></div><div className="mt-5 rounded-xl bg-[#f8f7f3] px-3 py-3"><p className="text-xs leading-5 text-[#435166]">{selectedTicket.detail}</p></div><div className="mt-6 space-y-4"><div className="flex gap-3"><span className="flex size-7 items-center justify-center rounded-full bg-[#007b78] text-white"><Check className="size-4" /></span><div><p className="text-sm font-extrabold">Request submitted</p><p className="mt-1 text-xs text-[#65707b]">NCRRA recorded your request.</p></div></div><div className="flex gap-3"><span className="flex size-7 items-center justify-center rounded-full border-2 border-[#007b78] bg-white"><span className="size-2 rounded-full bg-[#007b78]" /></span><div><p className="text-sm font-extrabold text-[#007b78]">Current: {selectedTicket.status}</p><p className="mt-1 text-xs text-[#65707b]">{selectedTicket.status === "Resolved" || selectedTicket.status === "Closed" ? "The latest action is available above." : "NCRRA will notify you when this changes."}</p></div></div><div className="flex gap-3"><span className="flex size-7 items-center justify-center rounded-full border border-[#cbd2d1] text-xs font-extrabold text-[#8a939d]">3</span><div><p className="text-sm font-extrabold text-[#6d7784]">Member confirmation</p><p className="mt-1 text-xs text-[#65707b]">You can review the outcome when the ticket closes.</p></div></div></div></div><button onClick={() => navigate("notifications")} className="app-press mt-4 flex w-full items-center justify-between rounded-xl border border-[#dce9e5] bg-[#f1f8f6] px-4 py-3"><span className="flex items-center gap-2 text-sm font-extrabold text-[#007b78]"><Bell className="size-4" /> You will receive updates here</span><ChevronRight className="size-4 text-[#007b78]" /></button></div></>;

    if (screen === "membership") return <><Header title="My membership" onBack={goBack} /><div className="px-5"><div className="rounded-2xl border border-[#dce9e5] bg-[#f1f8f6] p-4"><div className="flex gap-3"><Orb><HeartHandshake className="size-6" /></Orb><div><h2 className="font-display text-2xl font-extrabold tracking-[-0.06em]">NCRRA</h2><p className="mt-1 text-sm font-extrabold text-[#007b78]">● Active member</p></div></div><div className="mt-5 grid grid-cols-[1fr_auto] items-center border-t border-[#cbe2de] pt-4"><div className="space-y-2 text-xs"><p><span className="text-[#65707b]">Member ID</span><br /><b>NCRRA-000784</b></p><p><span className="text-[#65707b]">Valid until</span><br /><b>31 Dec 2025</b></p></div><div className="grid size-20 grid-cols-5 gap-0.5 rounded-md bg-white p-1">{Array.from({ length: 25 }, (_, index) => <span key={index} className={[0, 1, 4, 7, 10, 12, 16, 18, 20, 23, 24].includes(index) ? "bg-[#0b1e3b]" : "bg-[#e0e5e4]"} />)}</div></div></div><h2 className="mt-7 font-display text-[18px] font-extrabold">Annual contribution</h2><div className="mt-3 rounded-2xl border border-[#e3e6e5] bg-white p-4"><div className="flex items-center gap-3"><Orb tone="amber"><WalletCards className="size-5" /></Orb><div><p className="font-display text-2xl font-extrabold tracking-[-0.05em]">KES 6,000</p><Badge tone="amber">Due 01 Jul 2025</Badge></div></div><div className="mt-5"><PrimaryButton onClick={() => navigate("payment")}>Pay contribution</PrimaryButton></div><button onClick={() => navigate("receipt")} className="app-press mt-3 w-full text-sm font-extrabold text-[#007b78]">View receipts</button></div></div></>;

    if (screen === "payment") return <><Header title="Pay contribution" onBack={goBack} /><div className="px-5"><div className="rounded-2xl border border-[#e3e6e5] bg-white p-4"><p className="text-xs font-extrabold uppercase tracking-[0.12em] text-[#65707b]">Annual contribution</p><p className="mt-2 font-display text-3xl font-extrabold tracking-[-0.06em]">KES 6,000</p><div className="mt-4 border-t border-[#edf0ef] pt-4 text-xs"><div className="flex justify-between"><span className="text-[#65707b]">Member</span><b>NCRRA-000784</b></div><div className="mt-2 flex justify-between"><span className="text-[#65707b]">Due date</span><b>01 Jul 2025</b></div></div></div><h2 className="mt-7 font-display text-[18px] font-extrabold">Payment method</h2><div className="mt-3 space-y-3"><button onClick={() => setMethod("mpesa")} className={`app-press flex w-full items-center gap-3 rounded-2xl border-2 p-4 text-left ${method === "mpesa" ? "border-[#007b78] bg-[#f3fbfa]" : "border-[#e3e6e5] bg-white"}`}><Orb><Smartphone className="size-5" /></Orb><span className="flex-1"><span className="block text-sm font-extrabold">M-PESA</span><span className="mt-1 block text-xs text-[#65707b]">Confirm securely on your phone</span></span>{method === "mpesa" && <CircleCheck className="size-5 text-[#007b78]" />}</button><button onClick={() => setMethod("card")} className={`app-press flex w-full items-center gap-3 rounded-2xl border-2 p-4 text-left ${method === "card" ? "border-[#007b78] bg-[#f3fbfa]" : "border-[#e3e6e5] bg-white"}`}><Orb><CreditCard className="size-5" /></Orb><span className="flex-1"><span className="block text-sm font-extrabold">Card</span><span className="mt-1 block text-xs text-[#65707b]">Use a debit or credit card</span></span>{method === "card" && <CircleCheck className="size-5 text-[#007b78]" />}</button></div><div className="mt-5 rounded-xl bg-[#f1f8f6] px-3 py-3 text-xs leading-5 text-[#3c5558]"><ShieldCheck className="mr-1 inline size-4 text-[#007b78]" /> Payments are processed by an approved provider. NCRRA does not store your payment PIN.</div><div className="mt-6"><PrimaryButton onClick={() => setConfirming(true)}>Continue to {method === "mpesa" ? "M-PESA" : "card payment"}</PrimaryButton></div></div>{confirming && <div className="absolute inset-x-0 bottom-0 z-30 rounded-t-[28px] border-t border-[#dce1e0] bg-white p-5 shadow-[0_-10px_40px_rgba(11,30,59,0.14)]"><div className="mx-auto h-1.5 w-10 rounded-full bg-[#d7dcdb]" /><h3 className="mt-5 font-display text-xl font-extrabold">Confirm payment</h3><p className="mt-2 text-sm leading-6 text-[#5b6473]">A secure {method === "mpesa" ? "M-PESA prompt" : "payment page"} would open next. This prototype simulates a successful payment.</p><div className="mt-5"><PrimaryButton onClick={() => { setConfirming(false); navigate("receipt"); }}>Simulate successful payment</PrimaryButton></div><button onClick={() => setConfirming(false)} className="app-press mt-3 w-full text-sm font-extrabold text-[#007b78]">Cancel</button></div>}</>;

    if (screen === "receipt") return <><Header title="Contribution received" onBack={goBack} /><div className="px-5 pt-6 text-center"><span className="mx-auto flex size-16 items-center justify-center rounded-full bg-[#e8f5f2] text-[#007b78]"><Check className="size-9" /></span><h2 className="mt-5 font-display text-[24px] font-extrabold tracking-[-0.055em]">KES 6,000 paid successfully</h2><p className="mt-2 text-sm text-[#5b6473]">Your annual NCRRA contribution is recorded.</p><div className="mt-7 rounded-2xl border border-[#e3e6e5] bg-white p-4 text-left"><div className="space-y-4 text-sm"><div className="flex justify-between"><span className="text-[#65707b]">Reference</span><b>NCRRA-2025-00681</b></div><div className="flex justify-between"><span className="text-[#65707b]">Payment method</span><b>M-PESA</b></div><div className="flex justify-between"><span className="text-[#65707b]">Date</span><b>18 Jun 2025</b></div><div className="flex justify-between"><span className="text-[#65707b]">Membership status</span><b className="text-[#007b78]">Active</b></div></div></div><div className="mt-7"><PrimaryButton onClick={() => toast("Your receipt would download from the secure member account.")}><span className="flex items-center gap-2"><ReceiptText className="size-4" /> View receipt</span></PrimaryButton></div><button onClick={() => navigateRoot("home")} className="app-press mt-3 w-full text-sm font-extrabold text-[#007b78]">Back to home</button></div></>;

    if (screen === "community") return <><Header title="Community" action={<div className="flex gap-3"><Search className="size-6 text-[#007b78]" /><CalendarDays className="size-6 text-[#007b78]" /></div>} /><div className="border-b border-[#e3e6e5] px-5"><div className="grid grid-cols-3 text-center text-sm font-extrabold"><button className="border-b-4 border-[#007b78] pb-3 text-[#007b78]">Announcements</button><button className="pb-3 text-[#65707b]">Activities</button><button className="pb-3 text-[#65707b]">Events</button></div></div><div className="px-5 py-5"><div className="rounded-2xl border border-[#e3e6e5] bg-white p-4"><div className="flex gap-3"><Orb><CalendarDays className="size-5" /></Orb><div><p className="text-sm font-extrabold">NCRRA Annual General Meeting</p><p className="mt-2 flex items-center gap-1.5 text-xs text-[#5b6473]"><CalendarDays className="size-3.5" /> Saturday, 31 May 2025</p><p className="mt-1 flex items-center gap-1.5 text-xs text-[#5b6473]"><MapPin className="size-3.5" /> NCRRA Community Centre</p><button className="app-press mt-4 rounded-lg border border-[#007b78] px-3 py-2 text-xs font-extrabold text-[#007b78]">View details</button></div></div></div><div className="mt-4 rounded-2xl border border-[#e3e6e5] bg-white p-4"><div className="flex gap-3"><Orb tone="amber"><CircleAlert className="size-5" /></Orb><div><Badge tone="amber">Important</Badge><p className="mt-2 text-sm font-extrabold">Planned water maintenance</p><p className="mt-2 text-xs leading-5 text-[#5b6473]">Service may be interrupted between 09:00 and 14:00.</p></div></div></div></div></>;

    if (screen === "benefits") return <><Header title="Member benefits" action={<Search className="size-6 text-[#0b1e3b]" />} /><div className="px-5"><p className="-mt-2 text-sm text-[#5b6473]">Offers available to active NCRRA members</p><div className="mt-5 flex gap-2 overflow-x-auto pb-1"><Badge>All</Badge><Badge tone="slate">Travel</Badge><Badge tone="slate">Home</Badge><Badge tone="slate">Shopping</Badge></div><div className="mt-6 space-y-4"><div className="rounded-2xl border border-[#e3e6e5] bg-white p-4"><div className="flex gap-3"><Orb><Tag className="size-5" /></Orb><div className="flex-1"><p className="text-lg font-extrabold">15% off partner travel</p><p className="mt-1 text-sm font-bold text-[#007b78]">Travel</p><p className="mt-2 text-xs leading-5 text-[#5b6473]">Use your NCRRA member code when booking.</p><div className="mt-4 flex items-center justify-between"><Badge>Active</Badge><button className="app-press rounded-lg border border-[#007b78] px-3 py-2 text-xs font-extrabold text-[#007b78]">View offer</button></div></div></div></div><div className="rounded-2xl border border-[#e3e6e5] bg-white p-4"><div className="flex gap-3"><Orb><House className="size-5" /></Orb><div className="flex-1"><p className="text-lg font-extrabold">10% off home services</p><p className="mt-1 text-sm font-bold text-[#007b78]">Home</p><div className="mt-4 flex items-center justify-between"><Badge tone="coral">Ends in 5 days</Badge><button className="app-press rounded-lg border border-[#007b78] px-3 py-2 text-xs font-extrabold text-[#007b78]">View offer</button></div></div></div></div></div></div></>;

    if (screen === "notifications") return <><Header title="Notifications" onBack={goBack} action={<button onClick={() => toast("All notifications marked as read.")} className="text-xs font-extrabold text-[#007b78]">Mark all as read</button>} /><div className="px-5"><h2 className="text-sm font-extrabold">Today</h2><div className="mt-2 divide-y divide-[#e8ebea]"><ListRow icon={<Bell className="size-5" />} title="NCRRA Support updated NCRRA-2481" subtitle="11:20 AM" /><ListRow icon={<WalletCards className="size-5" />} title="Annual contribution due 01 Jul 2025" subtitle="09:00 AM" /></div><h2 className="mt-8 text-sm font-extrabold">Earlier</h2><div className="mt-2 divide-y divide-[#e8ebea]"><ListRow icon={<Tag className="size-5" />} title="New partner offer available" subtitle="Yesterday" /><ListRow icon={<Droplets className="size-5" />} title="Planned water maintenance" subtitle="14 May 2025" /></div><p className="mt-16 border-t border-[#e1e6e4] pt-5 text-xs leading-5 text-[#65707b]">You can manage notification preferences in <button onClick={() => navigate("account")} className="font-extrabold text-[#007b78]">Account</button>.</p></div></>;

    return <><Header title="Account" action={<button onClick={() => navigate("notifications")} className="app-press relative"><Bell className="size-6 text-[#0b1e3b]" /><span className="absolute -right-1 -top-1 flex size-4 items-center justify-center rounded-full bg-[#fa6b60] text-[9px] font-extrabold text-white">2</span></button>} /><div className="px-5"><button onClick={() => toast("Profile editing is included in the engineering handoff.")} className="app-press flex w-full items-center gap-3 rounded-2xl border border-[#e3e6e5] bg-white p-4 text-left"><Orb><UserRound className="size-5" /></Orb><span className="flex-1"><span className="block text-sm font-extrabold">Amina Wanjiku</span><span className="mt-1 block text-xs text-[#65707b]">amina@example.com</span></span><ChevronRight className="size-5" /></button><h2 className="mt-6 text-sm font-extrabold">Membership</h2><div className="mt-2 divide-y divide-[#e9eceb] rounded-2xl border border-[#e3e6e5] bg-white px-4"><ListRow onClick={() => navigate("membership")} icon={<CreditCard className="size-5" />} title="My membership" /><ListRow icon={<UsersRound className="size-5" />} title="Household and contacts" /><ListRow onClick={() => navigate("receipt")} icon={<ReceiptText className="size-5" />} title="My receipts" /></div><h2 className="mt-6 text-sm font-extrabold">Security</h2><div className="mt-2 divide-y divide-[#e9eceb] rounded-2xl border border-[#e3e6e5] bg-white px-4"><ListRow icon={<LockKeyhole className="size-5" />} title="Biometric login" end={<span className="h-6 w-11 rounded-full bg-[#007b78] p-1"><span className="block size-4 translate-x-5 rounded-full bg-white" /></span>} /><ListRow icon={<ShieldCheck className="size-5" />} title="Password and recovery" /><ListRow icon={<Smartphone className="size-5" />} title="Active devices" /></div><h2 className="mt-6 text-sm font-extrabold">Privacy</h2><div className="mt-2 divide-y divide-[#e9eceb] rounded-2xl border border-[#e3e6e5] bg-white px-4"><ListRow onClick={() => navigate("services")} icon={<PlugZap className="size-5" />} title="Provider connections" /><ListRow onClick={() => navigateRoot("membershipConsent")} icon={<ShieldCheck className="size-5" />} title="Consent and data access" /><ListRow onClick={() => navigate("notifications")} icon={<Bell className="size-5" />} title="Notification preferences" /></div><button onClick={() => navigateRoot("welcome")} className="app-press mt-5 flex w-full items-center justify-center gap-2 rounded-xl border border-[#007b78] py-3 text-sm font-extrabold text-[#007b78]"><UserRound className="size-4" /> Preview new member registration</button><button onClick={() => toast("Sign-out is disabled in the prototype.")} className="app-press mt-4 w-full text-sm font-extrabold text-[#dc5b43]">Sign out</button></div></>;
  };

  return <main className="grain min-h-screen bg-[#f8f7f3] px-4 py-6 text-[#0b1e3b] md:px-8 lg:px-12"><div className="mx-auto flex max-w-[1320px] items-start justify-center gap-8 xl:gap-12"><aside className="hidden w-[264px] shrink-0 pt-14 xl:block"><p className="text-xs font-extrabold uppercase tracking-[0.17em] text-[#007b78]">NCRRA clickable prototype</p><h2 className="mt-3 font-display text-[29px] font-extrabold leading-tight tracking-[-0.06em]">Member services and contribution flow.</h2><p className="mt-4 text-sm leading-6 text-[#5b6473]">Review connected interactions for registration, service routing, ticket tracking and annual contribution payment. Every action is a prototype simulation.</p><div className="mt-8 rounded-2xl border border-[#dce9e5] bg-[#f1f8f6] p-4"><p className="text-xs font-extrabold uppercase tracking-[0.12em] text-[#007b78]">Service issue flow</p><div className="mt-4 space-y-3">{serviceFlow.map((item, index) => <button key={item} onClick={() => navigateRoot(item)} className={`app-press flex w-full items-center gap-3 text-left text-sm ${screen === item ? "font-extrabold text-[#007b78]" : "font-bold text-[#5b6473]"}`}><span className={`flex size-6 items-center justify-center rounded-full text-[11px] ${screen === item ? "bg-[#007b78] text-white" : "bg-white text-[#65707b]"}`}>{index + 1}</span>{screenLabels[item]}</button>)}</div></div><div className="mt-4 rounded-2xl border border-[#e3e6e5] bg-white p-4"><p className="text-xs font-extrabold uppercase tracking-[0.12em] text-[#007b78]">New member flow</p><div className="mt-4 space-y-3">{registrationFlow.map((item, index) => <button key={item} onClick={() => navigateRoot(item)} className={`app-press flex w-full items-center gap-3 text-left text-sm ${screen === item ? "font-extrabold text-[#007b78]" : "font-bold text-[#5b6473]"}`}><span className={`flex size-6 items-center justify-center rounded-full text-[11px] ${screen === item ? "bg-[#007b78] text-white" : "bg-[#eef5f3] text-[#65707b]"}`}>{index + 1}</span>{screenLabels[item]}</button>)}</div></div></aside><section className="w-full max-w-[430px]"><div className="mx-auto overflow-hidden rounded-[34px] border-[7px] border-[#14233b] bg-[#f8f7f3] shadow-[0_30px_80px_rgba(11,30,59,0.22)]"><div className="h-6 bg-[#14233b]" /><div key={screen} className="relative flex min-h-[740px] max-h-[calc(100vh-88px)] flex-col overflow-y-auto bg-[#f8f7f3] screen-enter">{screenView()}{!onboardingScreen && <BottomNav active={activeNav} onNavigate={navigateRoot} />}</div></div></section><aside className="hidden w-[238px] shrink-0 pt-14 xl:block"><p className="text-xs font-extrabold uppercase tracking-[0.17em] text-[#007b78]">Visual reference set</p><p className="mt-3 text-sm leading-6 text-[#5b6473]">Generated UI specimens inform the service and billing flows. The phone in the centre is interactive UI, not a static image gallery.</p><div className="mt-5 grid grid-cols-2 gap-3">{visualReferences.map((item) => <div key={item.label} className="overflow-hidden rounded-xl border border-[#dce1e0] bg-white"><img src={item.src} alt={item.label} className="h-36 w-full object-cover object-top" /><p className="px-2 py-2 text-[10px] font-extrabold text-[#253752]">{item.label}</p></div>)}</div><button onClick={() => toast("This interactive flow is ready for member usability testing.")} className="app-press mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-[#0b1e3b] px-3 py-3 text-xs font-extrabold text-white"><FileText className="size-4" /> Prototype notes</button></aside></div></main>;
}
